/// Curated text for the catalogue sites and named feature centres
/// (`assets/data/curated_sites.json`), generated by `python -m
/// lunarsp.curated` from the committed research record. Never hand-edited.
///
/// The "overview engine" is called *glance* in code and "At a glance" in the
/// UI; its curated input is called *curated*.
library;

import 'dart:convert';

import 'catalog.dart';

/// A curated source. [titled] is false when no title was found in the repo
/// and the builder fell back to the host name (shown as, e.g., 'nasa.gov').
/// Titles are never invented.
class CuratedSource extends SiteSource {
  final bool titled;
  const CuratedSource(String title, String url, {this.titled = true}) : super(title, url, '');
}

/// Published-source text for one catalogue site.
class CuratedSite {
  final String id;

  /// One sentence, at most 80 characters, no final period.
  final String headline;

  /// Leading whole sentences of [overview], at most 230 characters.
  final String lede;

  /// The full overview (2 or more sentences), shown under "About this site".
  final String overview;

  /// [CuratedSource]s, in the order of the asset.
  final List<SiteSource> sources;

  const CuratedSite({
    required this.id,
    required this.headline,
    required this.lede,
    required this.overview,
    this.sources = const [],
  });
}

/// The IAU centre of a named feature (a crater or a mountain).
class NamedFeature {
  final String id, name, kind, url;
  final double lat, lon;

  /// Diameter in km, NaN when the research states none (for example Slater).
  final double diameterKm;

  const NamedFeature({
    required this.id,
    required this.name,
    required this.kind,
    required this.lat,
    required this.lon,
    this.diameterKm = double.nan,
    this.url = '',
  });
}

class CuratedCatalog {
  /// The only asset schema this code reads.
  static const int schemaVersion = 1;

  /// Curated entries by site id.
  final Map<String, CuratedSite> sites;
  final List<NamedFeature> features;

  /// When the research was reviewed, as written in the asset.
  final String reviewed;

  /// The rows [parse] dropped (a wrong shape or empty text), for the log:
  /// those sites fall back to the generated text, never to filler.
  final List<String> skipped;

  const CuratedCatalog({this.sites = const {}, this.features = const [], this.reviewed = '', this.skipped = const []});

  /// No curated text: every site gets the generated fallback.
  static const empty = CuratedCatalog();

  bool get isEmpty => sites.isEmpty && features.isEmpty;

  /// Parses `curated_sites.json`. Throws [FormatException] on bad JSON, an
  /// unknown `schema` or a wrong overall shape; the caller then uses [empty].
  /// A bad row (one site or feature of the wrong shape, or a site without a
  /// headline or overview) is dropped and named in [skipped]; the good rows
  /// are kept.
  static CuratedCatalog parse(String json) {
    final root = jsonDecode(json);
    if (root is! Map<String, dynamic>) throw const FormatException('curated: not a JSON object');
    final schema = root['schema'];
    if (schema != schemaVersion) throw FormatException('curated: unknown schema $schema');
    final rawSites = root['sites'] ?? const <String, dynamic>{};
    final rawFeatures = root['features'] ?? const [];
    if (rawSites is! Map<String, dynamic> || rawFeatures is! List) {
      throw const FormatException('curated: wrong shape (sites or features)');
    }
    final skipped = <String>[];
    T? row<T>(String what, T Function() read) {
      try {
        return read();
      } on TypeError catch (e) {
        skipped.add('$what ($e)');
      } on FormatException catch (e) {
        skipped.add('$what (${e.message})');
      }
      return null;
    }

    final sites = <String, CuratedSite>{};
    rawSites.forEach((id, v) {
      final site = row('site $id', () {
        final j = v as Map<String, dynamic>;
        final c = CuratedSite(
          id: id,
          headline: j['headline'] as String,
          lede: j['lede'] as String,
          overview: j['overview'] as String,
          sources: [
            for (final s in (j['sources'] as List? ?? const []))
              CuratedSource(
                ((s as Map<String, dynamic>)['title'] ?? '') as String,
                s['url'] as String,
                titled: (s['titled'] ?? true) as bool,
              ),
          ],
        );
        if (c.headline.trim().isEmpty || c.overview.trim().isEmpty) throw const FormatException('empty text');
        return c;
      });
      if (site != null) sites[id] = site;
    });
    double d(Object? x) => (x as num?)?.toDouble() ?? double.nan;
    final features = <NamedFeature>[];
    for (final (i, f) in rawFeatures.indexed) {
      final feature = row('feature $i', () => NamedFeature(
            id: (f as Map<String, dynamic>)['id'] as String,
            name: f['name'] as String,
            kind: (f['kind'] ?? '') as String,
            lat: d(f['lat']),
            lon: d(f['lon']),
            diameterKm: d(f['diameterKm']),
            url: (f['url'] ?? '') as String,
          ));
      if (feature != null) features.add(feature);
    }
    return CuratedCatalog(sites: sites, features: features, reviewed: '${root['reviewed'] ?? ''}', skipped: skipped);
  }
}
